import pytest
import json
from pathlib import Path
from validator import SwaggerSchemaValidator

# Load API spec for validation
api_spec_path = "api.json"
validator = SwaggerSchemaValidator(api_spec_path)

# Load test data from JSON file
_here = Path(__file__).resolve().parent
_endpoint_data_path = _here / "pet.json"
with open(_endpoint_data_path, "r") as f:
    _ENDPOINT_DATA = json.load(f)

# Reusable parametrize args
_PARAM_CASES = _ENDPOINT_DATA
_PARAM_IDS = [f"scenario_{i}" for i in range(len(_ENDPOINT_DATA))]

@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_update_pet(api_client, config_test_data, scenario_case):
    """
    Test the /pet endpoint for updating an existing pet.

    This test covers various scenarios including successful updates and validation errors.
    """
    endpoint = "/pet"
    method = "PUT"
    headers = {"Content-Type": "application/json"}
    data = {**config_test_data, **scenario_case}

    # Validate request schema before sending
    validator.validate_json(data, "Pet")

    # Make API request
    response = api_client.put(endpoint, data=json.dumps(data), headers=headers)

    # Validate response schema
    validation_result = validator.validate_schema_by_response(endpoint, method, str(response.status_code), response)
    assert validation_result["valid"], f"Schema validation failed: {validation_result.get('message', '')}"

    # Assert response status code
    expected_status_code = scenario_case.get("statusCode")
    assert response.status_code == expected_status_code, f"Expected {expected_status_code}, got {response.status_code}"

    # Additional assertions based on scenario
    if response.status_code == 200:
        response_data = response.json()
        assert "name" in response_data, "Response missing 'name'"
        assert "photoUrls" in response_data, "Response missing 'photoUrls'"
    elif response.status_code == 400:
        assert "Invalid ID supplied" in response.text
    elif response.status_code == 404:
        assert "Pet not found" in response.text
    elif response.status_code == 422:
        assert "Validation exception" in response.text
    elif response.status_code not in range(200, 300):
        assert "Unexpected error" in response.text
